# 1. Configure the Provider (AWS)
provider "aws" {
  region = "us-east-1"
}

# 2. Define a Virtual Server (EC2 Instance)
resource "aws_instance" "web_server" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.micro"

  tags = {
    Name        = "OpsAcademy-Web-Prod"
    Environment = "Production"
  }
}

# 3. Output the Public IP Address
output "server_public_ip" {
  value       = aws_instance.web_server.public_ip
  description = "The public IP address of our web server"
}

terraform {
  backend "s3" {
    bucket         = "opsacademy-tfstate-prod"
    key            = "global/s3/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}
